fn trunc_len(n: usize, m: usize) -> usize {
    if m == 0 {
        n
    } else if m >= n {
        1
    } else {
        n - m
    }
}

fn legder(c: Vec<f64>, m: u8, scl: f64) -> Vec<f64> {
    let n = c.len();
    let length = trunc_len(n, m as usize);
    
    // Return the appropriate slice of the vector
    c.iter().take(length).cloned().collect()
}

fn main() {
    // Example usage
    let array = vec![1.0, 2.0, 3.0, 4.0];
    let m = 2;
    let scl = 1.0; // This parameter is not used in the output
    let result = legder(array, m, scl);
    println!("{:?}", result); // Output should be [1.0, 2.0]
}